import csv,collections
rows=list(csv.DictReader(open('experiment3/model_loop/responses.csv')))
d=collections.defaultdict(list)
for r in rows:
  if ',' not in r['number_set']: d[(int(r['number_set']),int(r['target']))].append(int(r['rating']))
for s in sorted(set(k[0] for k in d)):
  print(s, ' '.join(f'{t}:{sum(v)}/{len(v)}' for (ss,t),v in sorted(d.items()) if ss==s))
sets=collections.Counter(r['number_set'] for r in rows); print(len(sets)); print(sets.most_common(60))
"; cat experiment3/model_loop/task_description.md | head -50

